// Convert CSV string to object array
let lines = msg.payload.split(/\r?\n/);
let headers = lines.shift().split(';');
msg.payload = lines.map(line => {
    let values = line.split(';');
    let obj = {};
    headers.forEach((h,i)=> obj[h.trim()] = values[i]?values[i].trim():null);
    return obj;
});
return msg;
